transforms.code:
# One alarm-status query per refresh for this UDT instance. Returns {key: code}:
# -1 = none, else state*10 + priority (state 0 active-acked, 1 active-unacked, 2 cleared-unacked;
# priority 0 Diagnostic .. 4 Critical). Replaces isAlarmActiveFiltered (gateway scope needs the
# provider in the path and Perspective never re-runs it on alarm changes).
out = {"FLT": -1, "HH": -1, "H": -1, "L": -1, "LL": -1, "OVR": -1, "UNR": -1}
tp = self.view.params.tagPath
if not tp:
	return out
tp = str(tp).strip()
prov = "*"
path = tp
if tp.startswith("[") and "]" in tp:
	prov = tp[1:tp.index("]")] or "*"
	path = tp[tp.index("]") + 1:]
path = path.strip("/")
keys = {"hw_fault": "FLT", "hh/alarm": "HH", "h/alarm": "H", "l/alarm": "L",
		"ll/alarm": "LL", "overrange": "OVR", "underrange": "UNR"}
try:
	events = system.alarm.queryStatus(source=["prov:%s:/tag:%s/*" % (prov, path)])
except Exception as e:
	system.util.getLogger("EFC_PV").warn("queryStatus failed for %s: %s" % (tp, e))
	return out
agg = {}
for ev in events:
	st = str(ev.getState())
	if st not in ("ActiveUnacked", "ActiveAcked", "ClearUnacked"):
		continue
	src = str(ev.getSource())
	if ":/tag:" not in src:
		continue
	tag = src.split(":/tag:", 1)[1].split(":/alm:", 1)[0].strip("/")
	if not tag.lower().startswith(path.lower() + "/"):
		continue
	key = keys.get(tag[len(path) + 1:].lower())
	if key is None:
		continue
	pri = int(ev.getPriority().ordinal())
	a = agg.setdefault(key, {"act": -1, "unack": False, "clr": -1})
	if st == "ClearUnacked":
		a["clr"] = max(a["clr"], pri)
	else:
		a["act"] = max(a["act"], pri)
		if st == "ActiveUnacked":
			a["unack"] = True
for key, a in agg.items():
	if a["act"] >= 0:
		out[key] = (10 if a["unack"] else 0) + a["act"]
	elif a["clr"] >= 0:
		out[key] = 20 + a["clr"]
return out

